#include <deque>
#include <list>
#include <memory>

int main() {
    // std::shared_ptr models the required shared ownership
    using IntPtr = std::shared_ptr<int>;

    IntPtr p1(new int(42));
    std::deque<IntPtr> coll1;
    std::list<IntPtr> coll2;

    // Insert same shared object into two containers
    coll1.push_back(p1); // Ref count = 2
    coll2.push_front(p1); // Ref count = 3

    // Modify via coll1 access
    *coll1.front() = 99;

    // coll2 sees the modification immediately
    // std::cout << *coll2.front(); // Output: 99
}
